import type { Carrier } from '../types.ts';

const S10_WEIGHTS = [8, 6, 4, 2, 3, 5, 9, 7];

/** S10 check digit for 8 serial digits (docs/carriers.md). */
export function s10CheckDigit(serial: string): number {
  const sum = S10_WEIGHTS.reduce((acc, weight, i) => acc + weight * Number(serial[i]), 0);
  const result = 11 - (sum % 11);
  if (result === 10) return 0;
  if (result === 11) return 5;
  return result;
}

/** UPU S10 as issued by Austrian Post: 2 letters, 8 digits, check digit, `AT`. Expects upper case. */
export function isValidAtpTrackingNumber(value: string): boolean {
  const match = /^[A-Z]{2}(\d{8})(\d)AT$/.exec(value);
  return match !== null && s10CheckDigit(match[1]) === Number(match[2]);
}

/**
 * Only ATP numbers are validated. Other carriers' formats change too often
 * (valid DHL numbers were rejected for two days last year), so anything non-empty is accepted.
 */
export function isValidTrackingNumber(carrier: Carrier, value: string): boolean {
  return carrier === 'ATP' ? isValidAtpTrackingNumber(value) : value !== '';
}
